package skills_test

import (
	"encoding/json"
	"os"
	"regexp"
	"strings"
	"testing"

	"github.com/forwardnetworks/fwdctl/skills"
)

// The NIST CSF 2.0 reference (generated by scripts/gen-csf-reference.py from NIST's own download) names the skills that evidence each subcategory. A name that is not a registered skill sends
// an assistant to nothing, so every skill-shaped name in the table must exist; each mapped row has the five cells and a level of evidence or partial, and the page keeps its warning that the CSF
// has no pass or fail.
func TestNISTCSFReferenceNamesOnlyRealSkillsAndKeepsItsCaveats(t *testing.T) {
	checkFrameworkReference(t, "plan-compliance-audit/reference/nist-csf-2.md", regexp.MustCompile(`^\| ([A-Z]{2}\.[A-Z]{2}-\d\d) \|`), 20,
		[]string{"no pass or fail", "Never answer \"compliant with the CSF\"", "not evidenced by Forward", "ours, not NIST's", "topic: security"})
}

// The DORA reference has the same rules: every skill, kind, view and input it names exists, each row has five cells and a level, and the page keeps its caveats and its pointer to the features view.
func TestDORAReferenceNamesOnlyRealSkillsAndKeepsItsCaveats(t *testing.T) {
	checkFrameworkReference(t, "plan-compliance-audit/reference/dora.md", regexp.MustCompile(`^\| (\d+[^|]*?) \|`), 9,
		[]string{"Never answer \"compliant with DORA\"", "not evidenced by Forward", "ours, not a regulator's", "topic: security", "our paraphrase"})
}

func checkFrameworkReference(t *testing.T, path string, rowRe *regexp.Regexp, minRows int, caveats []string) {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	text := string(b)
	known := map[string]bool{}
	for _, n := range skills.Names() {
		known[n] = true
	}
	prefix := regexp.MustCompile(`^(inspect|investigate|check|plan|verify|compare|edit|find|author|validate)-[a-z-]+$`)
	token := regexp.MustCompile("`([^`]+)`")
	rows := 0
	for _, line := range strings.Split(text, "\n") {
		m := rowRe.FindStringSubmatch(line)
		if m == nil {
			continue
		}
		rows++
		cells := strings.Split(strings.Trim(line, "| "), " | ")
		if len(cells) != 5 {
			t.Errorf("%s: %d cells, want 5: %q", m[1], len(cells), line)
			continue
		}
		if cells[2] != "evidence" && cells[2] != "partial" {
			t.Errorf("%s: level %q", m[1], cells[2])
		}
		named := 0
		cited := map[string]bool{}
		var others []string
		for _, tk := range token.FindAllStringSubmatch(cells[3], -1) {
			if prefix.MatchString(tk[1]) {
				named++
				cited[tk[1]] = true
				if !known[tk[1]] {
					t.Errorf("%s names %q, which is not a registered skill", m[1], tk[1])
				}
			} else {
				others = append(others, tk[1])
			}
		}
		if named == 0 {
			t.Errorf("%s names no skill", m[1])
		}
		// every other name in the cell is a kind, view or input of a skill the row cites (read from that skill's schema), or one of the listed non-skill names
		allowed := map[string]bool{}
		for sk := range cited {
			for v := range schemaNames(t, sk) {
				allowed[v] = true
			}
		}
		for _, o := range others {
			if !allowed[o] && !nonSkillNames[o] {
				t.Errorf("%s names %q: not a kind, view or input of %v, and not a listed non-skill name", m[1], o, keys(cited))
			}
		}
	}
	if rows < minRows {
		t.Errorf("%s: only %d mapped rows; the table is gone or the format changed", path, rows)
	}
	for _, want := range caveats {
		if !strings.Contains(text, want) {
			t.Errorf("%s lost %q", path, want)
		}
	}
}

// nonSkillNames are names a row may use that are not in a skill's schema: an NQE field of the data model.
var nonSkillNames = map[string]bool{"device.services": true, "reading-paths.md": true}

func keys(m map[string]bool) []string {
	var out []string
	for k := range m {
		out = append(out, k)
	}
	return out
}

// schemaNames returns every property name and every enum value in a skill's schema.json (its inputs, kinds, views and modes).
func schemaNames(t *testing.T, skill string) map[string]bool {
	t.Helper()
	b, err := os.ReadFile(skill + "/schema.json")
	if os.IsNotExist(err) { // a plan-* skill is a procedure with no input schema: it has no kinds or views to name
		return map[string]bool{}
	}
	if err != nil {
		t.Fatalf("%s: %v", skill, err)
	}
	var doc any
	if err := json.Unmarshal(b, &doc); err != nil {
		t.Fatalf("%s/schema.json: %v", skill, err)
	}
	out := map[string]bool{}
	var walk func(n any)
	walk = func(n any) {
		switch v := n.(type) {
		case map[string]any:
			for k, x := range v {
				if k == "properties" {
					if props, ok := x.(map[string]any); ok {
						for name := range props {
							out[name] = true
						}
					}
				}
				if k == "enum" {
					if vals, ok := x.([]any); ok {
						for _, e := range vals {
							if sv, ok := e.(string); ok {
								out[sv] = true
							}
						}
					}
				}
				walk(x)
			}
		case []any:
			for _, x := range v {
				walk(x)
			}
		}
	}
	walk(doc)
	return out
}
